mapper.select:
		SELECT A.RV_MEANING AS oggetto, B.RV_MEANING AS motivo, C.RV_MEANING AS esito
          FROM CG_REF_CODES A,
               CG_REF_CODES B,
               CG_REF_CODES C
         WHERE A.RV_DOMAIN = 'OGGETTO_PROCEDIMENTO'
           AND A.RV_LOW_VALUE = #{codiceOggetto}
           AND B.RV_DOMAIN = 'MOTIVO_PROVVEDIMENTO'
           AND B.RV_LOW_VALUE = #{codiceMotivo}
           AND C.RV_DOMAIN = 'ESITO_PROVVEDIMENTO'
           AND C.RV_LOW_VALUE = #{codiceEsito}
